/* From Uiverse.io by Zadrus  - Tags: simple, red, minimalist, gradient, loader, spinner, animated, gradients */
.__UIV_SCOPE__ .loading {
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .diamond {
  width: 50px;
  height: 50px;
  background-color: orange;
  clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
  margin: 5px;
  opacity: 0;
  animation: fade-in-out 1.5s ease-in-out infinite;
}

.__UIV_SCOPE__ .diamond.middle {
  transform: rotateY(180deg);
}

@keyframes fade-in-out {
  0%,
  100% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
}

.__UIV_SCOPE__ .diamond {
  background: linear-gradient(45deg, #ffba00, #ff6c00);
}

.__UIV_SCOPE__ .diamond:nth-child(1) {
  animation-delay: 0s;
}

.__UIV_SCOPE__ .diamond.middle {
  animation-delay: 0.5s;
}

.__UIV_SCOPE__ .diamond:nth-child(3) {
  animation-delay: 1s;
}
